function sustainedSpellScore(g,u,wave,p){
 let score=spellScore(p);
 const source={...u,side:'defender'},target={...wave,side:'monster',hp:1,status:{},traits:wave.traits??[]};
 for(const s of p.skills??[])if(s.status==='implemented'&&s.kind==='knives'&&s.cooldown===0){
  // These automatic spells are the phantom family's actual attack. Their
  // cadence is mana regeneration / mana cost, not an invented five-second
  // cooldown. Value sustained damage only, with the real target and damage
  // caps; initial mana and external mana auras grant no speculative bonus.
  score-=n(s.damage)*2/5;
  if(!matchesTargets(s,source,target)||profile(wave).skills?.some(s=>s.status==='implemented'&&s.kind==='immunity')||!(s.radius>0))continue;
  const cost=Math.max(0,n(s.manaCost)),capacity=Math.max(0,n(u.mana));
  if(cost>capacity)continue;
  const rate=Math.min(10,cost>0?Math.max(0,n(u.manaRegen))/cost:10);
  const count=Math.max(1,n(wave.count??wave.baseCount,108)),damage=Math.max(0,n(s.damage));
  const targets=Math.min(count,s.targetCap>0?s.targetCap:count,damage>0&&s.damageCap>0?s.damageCap/damage:count,12);
  const contacts=1+Math.max(0,targets-1)*(count>20?1:.15);
  score+=damage*contacts*rate*g._typeMultiplier('spells',wave.armorType,wave.sourceArmorTypeRaw);
 }
 return score;
}

/** Estimate the upcoming matchup using weapon masks and actual attack tables. */

// Apply the same frontline guard as new-build paths: transforming the
// only remaining frontliner into a ranged unit removes its protection.
if(gain>0&&(g.state.wave<4||!g._isFront(old)||g._isFront(next)||a.fronts.length>1))choices.push({type:'upgrade',u:units[targets[0]],b,targets,score:gain/Math.max(20,total+woodTotal*.75)*(a.defs.length>8?1.7:1.25)});

